#include <stdio.h>
#include <string.h>

#define N 5

typedef struct JCB
{
	char name[10];
	int arriveTime;  //到达时间 
	int serveTime;   //服务时间 
	int finishTime;  //完成时间 
	int aroundTime;  //周转时间 
	float waroundTime; //带权周转时间 
}PCB;



void input(PCB pcb[N])
{
	strcpy(pcb[0].name,"A");
	pcb[0].arriveTime = 0;
	pcb[0].serveTime = 3;

	strcpy(pcb[1].name,"B");
	pcb[1].arriveTime = 2;
	pcb[1].serveTime = 6;

	strcpy(pcb[2].name,"C");
	pcb[2].arriveTime = 4;
	pcb[2].serveTime = 4;

	strcpy(pcb[3].name,"D");
	pcb[3].arriveTime = 6;
	pcb[3].serveTime = 5;

	strcpy(pcb[4].name,"E");
	pcb[4].arriveTime = 8;
	pcb[4].serveTime = 2;

	int i = 0;
	for(; i < N; ++i)
	{
		pcb[i].finishTime = 0;
		pcb[i].aroundTime = 0;
		pcb[i].waroundTime = 0;
	}

}

void output(PCB pcb[N])
{
	int i = 0;
	printf("进程\t");
	printf("完成时间\t");
	printf("周转时间\t");
	printf("带权周转时间\t\n");
	for(; i < N; ++i)
	{
		printf("%s\t",pcb[i].name);
		printf("%d\t\t",pcb[i].finishTime);
		printf("%d\t\t",pcb[i].aroundTime);
		printf("%f\t\t\n",pcb[i].waroundTime);
	}
}

//先来先服务调度算法 
void FCFS(PCB pcb[N])
{
    int t = 0;
    while(1) {
        int min_t = -1;
        for(int i = 0; i < N; i++){
            if (pcb[i].finishTime != 0)continue;
            if (min_t == -1)min_t = i;
            if (pcb[i].arriveTime < pcb[min_t].arriveTime) min_t = i;
        }
        if (min_t == -1)break;
        if (pcb[min_t].arriveTime > t) t = pcb[min_t].arriveTime;
        pcb[min_t].finishTime = (t += pcb[min_t].serveTime);
        pcb[min_t].aroundTime = pcb[min_t].finishTime - pcb[min_t].arriveTime;
        pcb[min_t].waroundTime = (double)pcb[min_t].aroundTime / (double)pcb[min_t].serveTime;
    }
	//请补充先来先服务算法的实现代码
}



int main()
{
	PCB pcb[N];

	input(pcb);
	FCFS(pcb);
	printf("先来先服务FCFS:\n"); 
	output(pcb);
	printf("\n");

}
